using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BehenianHourglassOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/BehenianHourglassOmenData")]
public class BehenianHourglassOmenData : OnStartOfTurnOmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.BehenianHourglassActive = true;
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.BehenianHourglassActive = false;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return base.OmenConvertedDescription() + "\n" + base.localizationManager.GetLocalizedString("BehenianChakram_D");
	}
}
